import os, sys
CFG = '/app/config'
HIST = '/app/config-history'
def getfile(path, rev):
    rel = os.path.relpath(path, CFG)
    revs = sorted(int(d[1:]) for d in os.listdir(HIST) if d.startswith('r'))
    for r in revs:
        if r > rev:
            p = f'{HIST}/r{r:04d}/prev/{rel}'
            if os.path.exists(p):
                return open(p).read()
    return open(path).read()

def resolve(svcfile, svc, env, host, rev, cfgmap=None):
    out = {}
    def read(text, base, top_file):
        section = None
        for ln in text.splitlines():
            ln = ln.strip()
            if not ln or ln.startswith('#'): continue
            if ln.startswith('[') and ln.endswith(']'):
                section = ln[1:-1].strip(); continue
            k, _, v = ln.partition('=')
            k = k.strip(); v = v.strip()
            if k == 'include':
                if section is not None: continue
                v = v.replace('${env}', env).replace('${host}', host)
                p = os.path.normpath(os.path.join(base, v))
                read(getfile(p, rev), os.path.dirname(p), True)
                continue
            if top_file and section is not None and section != svc: continue
            out[k] = v
    d = os.path.dirname(svcfile)
    # service.conf: sections unused
    read(open(svcfile).read(), d, False)
    return out

if __name__ == '__main__':
    svc, env, host, rev = sys.argv[1], sys.argv[2], sys.argv[3], int(sys.argv[4])
    r = resolve(f'/app/services/{svc}/service.conf', svc, env, host, rev)
    print(svc, {k: r.get(k) for k in ['enabled', 'port_base', 'port_offset', 'admin_port']})
